local wraithSupport
do
    local env=getgenv()
    local previous=env.wraithRuntimeSupport
    if type(previous)=="table" and previous.Version==1 then wraithSupport=previous
    else
        local function api(name,fallback)
            local fn=env[name]
            return type(fn)=="function" and fn or type(fallback)=="function" and fallback or nil
        end
        local native={readfile=api("readfile",readfile),writefile=api("writefile",writefile),
            isfile=api("isfile",isfile),isfolder=api("isfolder",isfolder),listfiles=api("listfiles",listfiles),
            makefolder=api("makefolder",makefolder),getcustomasset=api("getcustomasset",getcustomasset),delfile=api("delfile",delfile)}
        local getter=api("getthreadidentity",getthreadidentity) or api("getidentity",getidentity)
        local setter=api("setthreadidentity",setthreadidentity) or api("setidentity",setidentity)
        local nativeRequire=require
        local support={Version=1,Files={}}


        local roots={string.char(107,105,99,105,97,114,101,98,117,105,108,100),string.char(107,105,99,105,97,104,111,111,107)}
        local oldRuntime=string.char(75,105,99,105,97,82,101,98,117,105,108,100)
        function support.PrepareLegacy()
            local old=env[oldRuntime]
            if type(old)=="table" and type(old.Unload)=="function" then
                local ok,problem=pcall(old.Unload)
                if not ok then warn("[Wraith.cc] Previous build cleanup: "..tostring(problem)) end
            end
            env[oldRuntime]=nil
        end
        function support.AssetURL(file)
            return "https://github.com/"..string.char(107,105,99,105,97,104,111,111,107,45,111,114,103).."/v3-assets/raw/refs/heads/main/"..file
        end
        function support.CallClient(callback,...)
            if not getter or not setter then return callback(...) end
            local read,old=pcall(getter)
            if not read or type(old)~="number" or old==2 then return callback(...) end
            local changed=pcall(setter,2)
            if not changed then return callback(...) end
            local result=table.pack(pcall(callback,...))
            local restored,restoreProblem=pcall(setter,old)
            if not restored then error("[Wraith.cc] Cannot restore caller context: "..tostring(restoreProblem),0) end
            if not result[1] then error(result[2],0) end
            return table.unpack(result,2,result.n)
        end
        function support.Require(...) return support.CallClient(nativeRequire,...) end
        local function normalize(path)
            return type(path)=="string" and path:gsub("\\","/"):gsub("^%./","") or path
        end
        local function relative(path,root)
            path=normalize(path)
            if type(path)~="string" then return nil end
            local lower=path:lower();root=root:lower()
            if lower==root then return "" end
            if lower:sub(1,#root+1)==root.."/" then return path:sub(#root+2) end
            local at=lower:find("/"..root.."/",1,true)
            return at and path:sub(at+#root+2) or nil
        end
        local function exists(fn,path)
            if not fn then return false end
            local ok,value=pcall(fn,path);return ok and value==true
        end
        local function legacy(path,kind)
            local tail=relative(path,"wraith")
            if tail==nil then return nil end
            for _,root in roots do
                local candidate=root..(tail~="" and "/"..tail or "")
                if exists(native[kind],candidate) then return candidate end
            end
        end
        local function ensureParents(path)
            local tail=relative(path,"wraith")
            if tail==nil or not native.makefolder then return end
            local parent="wraith"
            if not exists(native.isfolder,parent) then native.makefolder(parent) end
            local directory=tail:match("^(.*)/[^/]+$")
            if not directory then return end
            for segment in directory:gmatch("[^/]+") do
                parent..="/"..segment
                if not exists(native.isfolder,parent) then native.makefolder(parent) end
            end
        end
        local files=support.Files
        if native.isfile then files.isfile=function(path)
            return exists(native.isfile,path) or legacy(path,"isfile")~=nil
        end end
        if native.isfolder then files.isfolder=function(path)
            return exists(native.isfolder,path) or legacy(path,"isfolder")~=nil
        end end
        if native.readfile then files.readfile=function(path,...)
            local source=not exists(native.isfile,path) and legacy(path,"isfile") or nil
            return native.readfile(source or path,...)
        end end
        if native.writefile then files.writefile=function(path,...)
            ensureParents(path);return native.writefile(path,...)
        end end
        if native.makefolder then files.makefolder=native.makefolder end
        if native.delfile then files.delfile=function(path,...)
            local tail=relative(path,"wraith")
            if tail==nil then return native.delfile(path,...) end
            local deleted=false
            if exists(native.isfile,path) then native.delfile(path,...);deleted=true end


            for _,root in roots do
                local old=root..(tail~="" and "/"..tail or "")
                if exists(native.isfile,old) then native.delfile(old,...);deleted=true end
            end
            if not deleted then return native.delfile(path,...) end
        end end
        if native.getcustomasset then files.getcustomasset=function(path,...)
            local source=not exists(native.isfile,path) and legacy(path,"isfile") or nil
            return native.getcustomasset(source or path,...)
        end end
        if native.listfiles then files.listfiles=function(path)
            local tail=relative(path,"wraith")
            if tail==nil then return native.listfiles(path) end
            local result,seen={},{}
            local function collect(folder,root)
                if not exists(native.isfolder,folder) then return end
                local ok,items=pcall(native.listfiles,folder)
                if not ok or type(items)~="table" then return end
                for _,item in items do
                    local suffix=relative(item,root)
                    if suffix then
                        local current="wraith"..(suffix~="" and "/"..suffix or "")
                        local key=current:lower()
                        if not seen[key] then seen[key]=true;result[#result+1]=current end
                    end
                end
            end
            collect(path,"wraith")
            for _,root in roots do collect(root..(tail~="" and "/"..tail or ""),root) end
            return result
        end end
        env.wraithRuntimeSupport=support;wraithSupport=support
    end
end
local require=wraithSupport.Require
local readfile,writefile,isfile,isfolder,listfiles,makefolder,getcustomasset,delfile=
    wraithSupport.Files.readfile,wraithSupport.Files.writefile,wraithSupport.Files.isfile,
    wraithSupport.Files.isfolder,wraithSupport.Files.listfiles,wraithSupport.Files.makefolder,wraithSupport.Files.getcustomasset,wraithSupport.Files.delfile
wraithSupport.PrepareLegacy()



do
    local function waitForNativeReplication()
        if not game:IsLoaded() then game.Loaded:Wait() end
        local env=getgenv()
        local status={Version=2,Scope=tostring(game.GameId)..":"..tostring(game.JobId),
            Ready=false,Missing={},Unknown={},ListenerCounts={}}
        env.wraithNativeStartup=status
        local inspect=env.getconnections or getconnections
        if type(inspect)~="function" then
            status.Reason="inspection unavailable";status.CheckedAt=os.clock();return nil
        end
        local storage=game:GetService("ReplicatedStorage")
        local started=os.clock()
        local deadline=started+30
        repeat
            local remotes=storage:FindFirstChild("Remotes")
            local replication=remotes and remotes:FindFirstChild("Replication")
            table.clear(status.Missing);table.clear(status.Unknown)
            for _,name in {"Enemy","Fighter"} do
                local branch=replication and replication:FindFirstChild(name)
                local remote=branch and branch:FindFirstChild("ReplicateUnreliable")
                local count=0
                if remote and remote:IsA("UnreliableRemoteEvent") then
                    local ok,connections=pcall(inspect,remote.OnClientEvent)
                    if not ok or type(connections)~="table" then
                        status.ListenerCounts[name]=nil
                        table.insert(status.Unknown,name)
                        continue
                    end
                    for _,connection in connections do
                        local enabledOk,enabled=pcall(function() return connection.Enabled end)
                        local connectedOk,connected=pcall(function() return connection.Connected end)
                        if not (enabledOk and enabled==false) and not (connectedOk and connected==false) then count+=1 end
                    end
                end
                status.ListenerCounts[name]=count
                if count==0 then table.insert(status.Missing,name) end
            end
            local now=os.clock()
            status.CheckedAt=now;status.Waited=now-started
            if #status.Missing==0 then
                if #status.Unknown>0 then status.Reason="inspection unavailable";return nil end
                status.Ready=true;status.Reason="native listeners ready";return true
            end
            if now>=deadline then
                status.Reason="native listeners not ready before timeout"
                return false
            end
            task.wait(math.min(now-started<2 and .1 or .25,deadline-now))
        until false
    end


    if waitForNativeReplication()==false then
        local status=getgenv().wraithNativeStartup
        warn("[Wraith.cc] Loading stopped: game replication listeners missing ("..
            table.concat(status.Missing,", ").."). Rejoin before running the script.")
        return
    end
end



