    if type(previousPrefix)=="table" and previousPrefix.Scope==prefixScope and previousPrefix.Revision==prefixRevision then
        if previousPrefix.Installed then return end
        if type(previousPrefix.Thread)=="thread" and coroutine.status(previousPrefix.Thread)~="dead" then return end
    end
    local prefixState={Scope=prefixScope,Revision=prefixRevision,Thread=coroutine.running(),Installed=false}
    prefixEnv.wraithCosmeticPrefixState=prefixState
local plrs = game:GetService("Players")
