	pcall(function() part.Reflectance = 0 end)
	pcall(function() part.Size = Vector3.new(0.001, 0.001, 0.001) end)
	part:SetAttribute("__MeowHiddenSniperMesh", true)
	part:SetAttribute("__MeowCustomSniperHiddenPart", true)
