	registerVirtualWeaponSkin(SPIKE_TRIPMINE_SKIN, "Subspace Tripmine", "Subspace Tripmine", "Contraband", "Spike", SPIKE_TRIPMINE_SKIN)
end

registerVirtualWeaponSkins()
task.spawn(function()
	for _ = 1, 60 do
		task.wait(1)
		for name in pairs(CUSTOM_SKIN_NAMES) do
			local data = coss[name]
			if data and (not data.Image or data.Image == "") then
				local vmName = data.SourceViewModelName or data.ViewModelName
				local vm = ilib and ilib.ViewModels and vmName and ilib.ViewModels[vmName]
				local img = (vm and (vm.Image or vm.ImageHighResolution)) or ""
				local hi = (vm and (vm.ImageHighResolution or vm.Image)) or ""
				if img ~= "" then
					data.Image = img
					data.ImageHighResolution = hi
					if ilib and ilib.ViewModels and ilib.ViewModels[name] then
						ilib.ViewModels[name].Image = img
						ilib.ViewModels[name].ImageHighResolution = hi
					end
				end
				if (not data.Image or data.Image == "") and consts and consts.COSMETIC_IMAGES then
					local ci = consts.COSMETIC_IMAGES[vmName] or consts.COSMETIC_IMAGES[name]
					if type(ci) == "table" then
						data.Image = ci.Image or ci.ImageHighResolution or ci.Texture or ci.Icon or data.Image or ""
						data.ImageHighResolution = ci.ImageHighResolution or ci.Image or data.Image or ""
					elseif type(ci) == "string" and ci ~= "" then
						data.Image = ci
						data.ImageHighResolution = ci
					end
				end
			end
		end
	end
end)

