local function fn35()
local Spec = tbl17.kL()
local Runtime = tbl17.kM()
local UI = {}

function UI.Build(context, rootTab)
    local adapter = context.ReactiveStoreAdapter
    local engine = Runtime.new(context)
    context.HvhOwner:Add(engine)
    context.HvhBindRuntime(engine)
    local pages = {}
    local labels = {FakePosition="Fake Position",VoidSpam="Voidspam", Orbit="Orbit", Prediction="Prediction", Defense="Defense",
        Translocation="Translocation", SlingBypass="Sling Bypass", Riot="Riot"}
    local icons = {FakePosition="rbxassetid://6034509993",VoidSpam="rbxassetid://6034684949", Orbit="rbxassetid://6034509993",
        Prediction="rbxassetid://6034509993", Defense="rbxassetid://6034767618",
        Translocation="rbxassetid://6034509993", SlingBypass="rbxassetid://6034509993", Riot="rbxassetid://6034684949"}
    for _, panel in ipairs(Spec.Panels) do
        local grid = pages[panel.Tab]
        if not grid then
            grid = rootTab:AddTab({Label=labels[panel.Tab],Icon=icons[panel.Tab]}):Grid({Columns=2})
            pages[panel.Tab] = grid
        end
        local section = grid:AddSection({Title=panel.Title,Side=panel.Side})
        for _, c in ipairs(panel.Controls) do
            local path = {"HvH","Values",c.Id}
            local label=c.Label..(c.ReferenceOnly and " (reference only)" or "")
            if c.Kind == "Toggle" then
                local toggle = section:AddToggle({Label=label,Default=c.Default,Config=path})
                local function bindPath(field) return {"HvH","Binds",c.Id,field} end
                local bind = section:AddKeybind({Row=toggle.Row,Modes={"Always","Toggle","Hold"},
                    InKeybindList=not c.ReferenceOnly,ListLabel=c.Label,ConfigMap={Key=bindPath("Bind"),Mode=bindPath("Kind"),
                    Active=bindPath("State"),ShowInList=bindPath("ShowInList"),Invisible=bindPath("Invisible")}})
                bind:SetFeatureEnabled(toggle.Value)
                toggle:Connect(toggle.ValueChanged,function(v) bind:SetFeatureEnabled(v) end)
            elseif c.Kind == "Slider" then
                section:AddSlider({Label=label,Default=c.Default,Min=c.Min,Max=c.Max,Step=c.Step,Config=path})
            else
                section:AddDropdown({Label=label,Default=c.Default,Options=c.Options,Config=path})
            end
        end
    end
    local function sync() engine:Sync(adapter:Get({"HvH"})) end
    context.HvhOwner:Add(adapter:Changed({"HvH"},true):Connect(sync))
    sync()
    return engine
end
return UI

end
