function UI.BuildAuras(context,grid)
    local function P(...) return path("VisualAuras",...) end
    local main=grid:AddSection({Title="Aura Theme",Side="left"})
    main:AddToggle({Label="Enable Auras",Config=P("Enabled")})
    main:AddToggle({Label="Hide My Aura In First Person",Config=P("HideInFirstPerson")})
    main:AddSlider({Label="Camera Hide Distance",Min=1,Max=6,Step=.1,Config=P("CameraHideDistance")})
    main:AddDropdown({Label="Aura Source",Options={"Particle Aura","Model Aura","Wings & Halo"},Config=P("AuraSource")})
    main:AddDropdown({Label="Particle Effect",Options={"Angelic","Ambient","Nimb","Tornado","Comet"},Config=P("ParticleEffect")})
    main:AddDropdown({Label="Model Effect",Options={"Angel","Starlight","Heavenly","Ribbon","Sakura","Wind","Flow","Star"},Config=P("ModelEffect")})
    main:AddToggle({Label="Keep Model Colors In Theme Mode",Config=P("KeepModelColors")})
    main:AddButton({Label="Retry Model Load",OnClick=function()
        local store=context.ReactiveStoreAdapter
        store:Set(P("ModelReload"),(store:Get(P("ModelReload")) or 0)+1)
    end})
    main:AddLabel({Label="Unavailable models use the selected particle effect."})
    main:AddDropdown({Label="Theme",Options={"Angel","Demon","Fallen Angel","Celestial"},Config=P("Theme")})
    main:AddDropdown({Label="Targets",Options={"Local Player","Enemies","Teammates","Everyone"},Config=P("Targets")})
    main:AddDropdown({Label="Color Mode",Options={"Theme Colors","Custom Colors","Menu Accent"},Config=P("ColorMode")})
    local function customColor()
        local adapter=context.ReactiveStoreAdapter
        if adapter then
            adapter:Set(P("ColorMode"),"Custom Colors")
            adapter:Set(P("KeepModelColors"),false)
        end
    end
    local primary=main:AddLabel({Label="Custom Primary Color"})
    main:AddColor({Row=primary.Row,Config=P("Color"),Animatable=true,OnChanged=customColor})
    local secondary=main:AddLabel({Label="Custom Secondary Color"})
    main:AddColor({Row=secondary.Row,Config=P("SecondaryColor"),Animatable=true,OnChanged=customColor})
    main:AddSlider({Label="Overall Size",Min=.5,Max=2.5,Step=.05,Config=P("Scale")})
    main:AddSlider({Label="Overall Opacity",Min=0,Max=1,Step=.01,Config=P("Opacity")})

    local light=grid:AddSection({Title="Glow & Lighting",Side="right"})
    light:AddToggle({Label="Enable Glow",Config=P("GlowEnabled")})
    light:AddSlider({Label="Glow Strength",Min=0,Max=2,Step=.05,Config=P("GlowStrength")})
    light:AddSlider({Label="Beam Glow Spread",Min=.1,Max=2,Step=.05,Config=P("GlowWidth")})
    light:AddSlider({Label="Effect Brightness",Min=0,Max=8,Step=.1,Config=P("Brightness")})
    light:AddToggle({Label="Illuminate Surroundings",Config=P("WorldLight")})
    light:AddSlider({Label="Light Brightness",Min=0,Max=4,Step=.1,Config=P("LightBrightness")})
    light:AddSlider({Label="Light Range",Min=0,Max=32,Step=1,Config=P("LightRange")})
    light:AddToggle({Label="Character Glow",Config=P("BodyGlow")})
    light:AddSlider({Label="Body Fill Opacity",Min=0,Max=1,Step=.01,Config=P("FillOpacity")})
    light:AddSlider({Label="Body Outline Opacity",Min=0,Max=1,Step=.01,Config=P("OutlineOpacity")})
    light:AddToggle({Label="Body Glow Through Walls",Config=P("ThroughWalls")})

    local wings=grid:AddSection({Title="Sculpted Wings & Crown",Side="left"})
    wings:AddToggle({Label="Wings / Celestial Orbitals",Config=P("Wings")})
    wings:AddSlider({Label="Wing Span",Min=3,Max=14,Step=.25,Config=P("WingSpan")})
    wings:AddSlider({Label="Feather / Membrane Length",Min=.4,Max=2,Step=.05,Config=P("WingLength")})
    wings:AddSlider({Label="Wing / Orbital Opacity",Min=0,Max=1,Step=.01,Config=P("WingOpacity")})
    wings:AddSlider({Label="Back Offset",Min=0,Max=3,Step=.05,Config=P("BackOffset")})
    wings:AddToggle({Label="Animate Wings",Config=P("WingFlap")})
    wings:AddSlider({Label="Wing Motion Speed",Min=.1,Max=3,Step=.05,Config=P("WingSpeed")})
    wings:AddSlider({Label="Wing Motion Amount",Min=0,Max=35,Step=1,Config=P("WingFlapAmount")})
    wings:AddToggle({Label="Halo / Demon Horns",Config=P("Crown")})
    wings:AddSlider({Label="Crown Height",Min=1.5,Max=5,Step=.1,Config=P("CrownHeight")})
    wings:AddSlider({Label="Crown Size",Min=.5,Max=2,Step=.05,Config=P("CrownScale")})
    wings:AddToggle({Label="Demon Tail",Config=P("Tail")})
    wings:AddSlider({Label="Demon Tail Length",Min=1,Max=6,Step=.1,Config=P("TailLength")})

    local particles=grid:AddSection({Title="Particles",Side="right"})
    particles:AddToggle({Label="Theme Particles",Config=P("Particles")})
    particles:AddSlider({Label="Particle Density",Min=0,Max=40,Step=1,Config=P("ParticleRate")})
    particles:AddSlider({Label="Particle Size",Min=.05,Max=1.2,Step=.05,Config=P("ParticleSize")})
    particles:AddSlider({Label="Particle Speed",Min=0,Max=5,Step=.1,Config=P("ParticleSpeed")})
    particles:AddSlider({Label="Particle Lifetime",Min=.3,Max=3,Step=.1,Config=P("ParticleLifetime")})
    particles:AddToggle({Label="Leave Particle Trails",Config=P("ParticleTrails")})

    local comet=grid:AddSection({Title="Comet Trails",Side="right"})
    comet:AddSlider({Label="Orbit Radius",Min=.1,Max=4,Step=.05,Config=P("CometRadius")})
    comet:AddSlider({Label="Trail Detail",Min=6,Max=24,Step=1,Config=P("CometTrailLength")})
    comet:AddSlider({Label="Trail Spacing",Min=.2,Max=5,Step=.1,Config=P("CometSpacing")})
    comet:AddSlider({Label="Trail Width",Min=.015,Max=.15,Step=.005,Config=P("CometWidth")})
    comet:AddSlider({Label="Comet Head Size",Min=.05,Max=.5,Step=.01,Config=P("CometHeadSize")})

    local motion=grid:AddSection({Title="Aura Animation",Side="left"})
    motion:AddSlider({Label="Animation Speed",Min=0,Max=3,Step=.1,Config=P("AnimationSpeed")})
    motion:AddToggle({Label="Pulse",Config=P("Pulse")})
    motion:AddSlider({Label="Pulse Speed",Min=.1,Max=5,Step=.1,Config=P("PulseSpeed")})
    motion:AddSlider({Label="Pulse Strength",Min=0,Max=.8,Step=.01,Config=P("PulseStrength")})

    local seal=grid:AddSection({Title="Optional Ground Seal",Side="right"})
    seal:AddToggle({Label="Ground Seal",Config=P("GroundSeal")})
    seal:AddSlider({Label="Seal Radius",Min=.5,Max=12,Step=.1,Config=P("Radius")})
    seal:AddSlider({Label="Seal Line Width",Min=.02,Max=.5,Step=.01,Config=P("RingWidth")})
    seal:AddSlider({Label="Seal Opacity",Min=0,Max=1,Step=.01,Config=P("RingOpacity")})
    seal:AddSlider({Label="Seal Height Offset",Min=-3,Max=8,Step=.05,Config=P("HeightOffset")})
    seal:AddToggle({Label="Follow Ground",Config=P("GroundFollow")})
    seal:AddSlider({Label="Seal Spin Speed",Min=-360,Max=360,Step=5,Config=P("SpinSpeed")})

    local budget=grid:AddSection({Title="Aura Visibility & Detail",Side="left"})
    budget:AddDropdown({Label="Detail",Options={"Low","Balanced","High"},Config=P("Quality")})
    budget:AddSlider({Label="Maximum Distance",Min=10,Max=2000,Step=10,Config=P("MaxDistance")})
    budget:AddSlider({Label="Maximum Targets",Min=1,Max=8,Step=1,Config=P("MaxTargets")})
    budget:AddSlider({Label="Settings Update Rate",Min=10,Max=60,Step=5,Config=P("UpdateRate")})
end

return UI

end
