            inputX=input.Position.X,inputY=input.Position.Y,x=self._x or 0,y=self._y or 0}
    end)
    self._trove:Connect(self._services.UserInputService.InputChanged,function(input)
        local drag=self._drag
        if not drag then return end
        if (drag.touch and input~=drag.input) or (not drag.touch and input.UserInputType~=Enum.UserInputType.MouseMovement) then return end
        local x=drag.x+input.Position.X-drag.inputX
        local y=drag.y+input.Position.Y-drag.inputY
        self:_Place(x,y)
    end)
    self._trove:Connect(self._services.UserInputService.InputEnded,function(input)
        local drag=self._drag
        if drag and ((drag.touch and input==drag.input) or (not drag.touch and input.UserInputType==Enum.UserInputType.MouseButton1)) then self:_EndDrag() end
    end)
    self:_Style()
end
function Panel:_Bounds()
    for _,parent in {self._layer,self._menu._gui} do
        local size=parent and parent.AbsoluteSize
        if size and size.X>0 and size.Y>0 then return size.X,size.Y end
    end
    local camera=workspace.CurrentCamera
    local viewport=camera and camera.ViewportSize
    return viewport and viewport.X or 800,viewport and viewport.Y or 600
end

function Panel:_Place(x,y)
    local w,h=self:_Bounds()
    x=math.round(number(x,0,0,math.max(0,w-self._width)))
    y=math.round(number(y,0,0,math.max(0,h-self._height)))
    if self._x==x and self._y==y then return end
    self._x=x;self._y=y;self._root.Position=UDim2.fromOffset(x,y)
end
function Panel:_Layout()
    if not self._root then return end
    local config=self:_Config()
    local w,h=self:_Bounds()
    local textSize=number(config.FontSize,14,8,24)
    local width=math.min(number(config.Width,264,180,360),math.max(1,w-16))
    local headerExtra=14
    local height=math.min(textSize*2+64+headerExtra,math.max(1,h-8))
    local segments=math.round(number(config.BarSegments,20,8,32))
    local pixel=config.PixelStyle~=false;local showBar=config.ShowBar~=false
    local px=number(config.PositionX,.72,0,1);local py=number(config.PositionY,.62,0,1)
    local coordinateSize=math.min(math.clamp(textSize-4,8,11),width<240 and 8 or 11)
    if self._position.TextSize~=coordinateSize then self._position.TextSize=coordinateSize end
    local last=self._layoutState
    if last and last[1]==w and last[2]==h and last[3]==width and last[4]==height and last[5]==textSize
        and last[6]==segments and last[7]==pixel and last[8]==showBar and last[9]==px and last[10]==py then return end
    self._layoutState={w,h,width,height,textSize,segments,pixel,showBar,px,py}
    self._width=width;self._height=height
    self._root.Size=UDim2.fromOffset(self._width,self._height)
    self._header.Size=UDim2.new(1,0,0,23+headerExtra)
    self._title.Position=UDim2.fromOffset(10,3);self._title.Size=UDim2.fromOffset(78,17)
    self._status.Position=UDim2.new(1,-54,0,3);self._status.Size=UDim2.fromOffset(44,17)
    self._position.Position=UDim2.fromOffset(12,18)
    self._position.Size=UDim2.new(1,-24,0,17)
    self._name.Position=UDim2.fromOffset(12,27+headerExtra);self._name.Size=UDim2.new(1,-24,0,textSize+6)
    self._health.Position=UDim2.fromOffset(12,textSize+33+headerExtra);self._health.Size=UDim2.new(1,-24,0,textSize+6)
    self._barBack.Position=UDim2.new(0,12,1,-24);self._barBack.Size=UDim2.new(1,-24,0,12)
    self._barBack.Visible=config.ShowBar~=false
    for i,gap in self._gaps do
        gap.Visible=config.PixelStyle~=false and i<segments
        gap.Position=UDim2.fromScale(i/segments,0)
    end
    if self._drag then self:_Place(self._x,self._y)
    else self:_Place(number(config.PositionX,.72,0,1)*math.max(0,w-self._width),number(config.PositionY,.62,0,1)*math.max(0,h-self._height)) end
end

function Panel:_Font(name)
    if name=="Arcade" then return Font.fromEnum(Enum.Font.Arcade) end
    local face=self._fonts:Get(name or "Minecraftia")
    if name=="Minecraftia" and (typeof(face)~="Font" or face.Family==Font.fromEnum(Enum.Font.SourceSans).Family) then
        return Font.fromEnum(Enum.Font.Arcade)
    end
    return face
end
function Panel:_Style()
    if not self._root or self._destroyed then return end
    local config=self:_Config()
    local background=color(self._theme.get("Background"),Color3.fromRGB(15,15,18))
    if config.UseMenuColors==false then background=color(config.BackgroundColor,background) end
    local opacity=number(config.BackgroundOpacity,.94,0,1)
    self._root.BackgroundColor3=background;self._root.BackgroundTransparency=1-opacity
    self._header.BackgroundColor3=background:Lerp(WHITE,.065);self._header.BackgroundTransparency=1-opacity
    local pixel=config.PixelStyle~=false
    self._corner.CornerRadius=UDim.new(0,pixel and 0 or number(config.CornerRadius,6,0,12))
    for _,corner in self._barCorners do corner.CornerRadius=UDim.new(0,pixel and 0 or 3) end
    local font=self:_Font(config.Font)
    local textColor=color(config.TextColor,WHITE)
    local size=number(config.FontSize,14,8,24)
    for _,label in {self._name,self._health,self._title,self._status} do label.FontFace=font;label.TextColor3=textColor;label.TextSize=size end
    self._position.FontFace=font;self._position.TextColor3=textColor
    self._title.TextSize=math.clamp(size-4,8,11);self._status.TextSize=self._title.TextSize
    self._position.TextTransparency=.15
    local accent=color(self._theme.get("Accent"),Color3.fromRGB(255,143,222))
    for _,glow in self._cornerGlow do glow.BackgroundColor3=accent end
    self._title.TextTransparency=.3;self._health.TextTransparency=.1
    for _,stroke in {self._nameStroke,self._healthStroke,self._titleStroke,self._statusStroke,self._positionStroke} do stroke.Enabled=pixel end
    self._barBack.BackgroundColor3=background:Lerp(WHITE,.12);self._barBack.BackgroundTransparency=1-opacity
    for _,gap in self._gaps do gap.BackgroundColor3=self._barBack.BackgroundColor3;gap.BackgroundTransparency=1-opacity end
    self:_Layout();self:_Interactable()
    if self._identity~=nil then self:_PaintBar(self._ratio or 0,self._waiting,true) end
end
function Panel:_UpgradeDesign()
    if self._upgrading then return end
    local config=self:_Config()
    if number(config.PixelDesignVersion,0,0,100)>=1 then return end
    self._upgrading=true
    local store=self._context.ReactiveStoreAdapter
    if config.Font==nil or config.Font=="Inconsolata" then store:Set(path("Font"),"Minecraftia") end
    store:Set(path("PixelDesignVersion"),1)
    self._upgrading=false
end

function Panel:_Interactable()
    if self._root then self._root.Active=self._menu.Visible==true and self:_Config().Movable~=false end
end
function Panel:_EndDrag()
    if not self._drag then return end
    self._drag=nil
    local w,h=self:_Bounds()
    local x=math.max(0,w-self._width);local y=math.max(0,h-self._height)
    local savedX=x>0 and math.clamp(self._x/x,0,1) or 0
    local savedY=y>0 and math.clamp(self._y/y,0,1) or 0
    local adapter=self._context.ReactiveStoreAdapter
    adapter:Set(path("PositionX"),savedX)
    adapter:Set(path("PositionY"),savedY)
end
function Panel:_Local()
    local context=self._context.HvhPlayerContext
    local inner=context and context.Inner
    local fighters=self._context.HvhFighters
    return inner and inner.FighterState or fighters and fighters.LocalState
end

function Panel:_IsTeammate(player)
    if not player then return false end
    local players=self._services.Players
    local state=self:_Local()
    local own=players and players.LocalPlayer or (state and state.Player)
    if not own then return false end
    if player==own then return true end
    local ownId=type(own.GetAttribute)=="function" and own:GetAttribute("TeamID") or nil
    local targetId=type(player.GetAttribute)=="function" and player:GetAttribute("TeamID") or nil


    if ownId~=nil and targetId~=nil then return ownId==targetId end
    return own.Neutral~=true and player.Neutral~=true and own.Team~=nil and own.Team==player.Team
end
function Panel:_ReadFighter(fighter)
    local fighters=self._context.HvhFighters
    local localState=self:_Local()
    if not fighter or not fighters or not localState or localState.IsSpectating or localState.EnvironmentId==nil then return nil end
    local localCharacter=localState.Character and localState.Character.State
    if not localCharacter or not localCharacter.Alive then return nil end
    local player=fighter.Player
    if not player or not player.Parent or not fighters.StateByPlayer or fighters.StateByPlayer[player]~=fighter then return nil end
    if fighter.IsEnemy~=true or fighter.EnvironmentId~=localState.EnvironmentId or self:_IsTeammate(player) then return nil end
    local state=fighter.Character and fighter.Character.State
    if not state or not state.Alive or not state.Model or not state.Model.Parent then return nil end
    local humanoid=state.Humanoid
    local hp=humanoid and humanoid.Health or state.Health
    local maximum=humanoid and humanoid.MaxHealth or state.MaxHealth
    if not finite(hp) or not finite(maximum) or hp<=0 or maximum<=0 then return nil end
    return {fighter=fighter,state=state,hp=math.clamp(hp,0,maximum),maximum=maximum,player=player}
end
function Panel:_ReadModel(model,allowDead,confirmed)
    if typeof(model)~="Instance" or not model:IsA("Model") or not model.Parent then return nil end
    local localState=self:_Local()
    local localCharacter=localState and localState.Character and localState.Character.State
    if not localState or not localCharacter or not localCharacter.Alive or localState.IsSpectating then return nil end
    if localCharacter.Model==model then return nil end
    local fighters=self._context.HvhFighters
    local fighter=fighters and fighters.StateByModel and fighters.StateByModel[model]
    if fighter and fighter.IsEnemy==false then return nil end
    if not confirmed and fighter then return self:_ReadFighter(fighter) end
    local players=self._services.Players
    local player=players and players:GetPlayerFromCharacter(model)
    if player and player==players.LocalPlayer then return nil end
    if player and (not player.Parent or player.Character~=model or self:_IsTeammate(player)) then return nil end
    if not confirmed then
        if player then
            if localState.EnvironmentId==nil or player:GetAttribute("EnvironmentID")~=localState.EnvironmentId then return nil end
        else
            local registry=self._context.TargetHealthEnemies
            if not registry or not registry._objectIdByModel or registry._objectIdByModel[model]==nil then return nil end
        end
    end
    local humanoid=model:FindFirstChildOfClass("Humanoid")
    if not humanoid then return nil end
    local hp,maximum=humanoid.Health,humanoid.MaxHealth
    if not finite(hp) or not finite(maximum) or maximum<=0 or hp<0 or (hp==0 and not allowDead) then return nil end
    local part=model:FindFirstChild("HitboxHead") or model:FindFirstChild("Head") or model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
    return {model=model,state=humanoid,humanoid=humanoid,hp=math.clamp(hp,0,maximum),maximum=maximum,
        player=player,name=model.Name,part=part,confirmed=confirmed==true}
end
function Panel:_FromHitPart(part)
    if typeof(part)~="Instance" then return nil end
    local node=part
    for _=1,8 do
        if not node then break end
        if node:IsA("Model") then
            local entry=self:_ReadModel(node,true,true)
            if entry then return entry end
        end
        node=node.Parent
    end
    return nil
end
function Panel:_OnDamage(packet)
    if self._destroyed or self:_Config().Enabled~=true or type(packet)~="table" or packet.EnumName~="DamageNumberEffect" then return end
    local owner=self:_Local()
    if not owner or owner.ObjectId==nil or packet.ObjectId~=owner.ObjectId then return end
    local args=packet.Args
    if type(args)~="table" or not finite(args[2]) or args[2]<=0 or typeof(args[1])~="Instance" then return end
    local now=os.clock()
    local last=self._lastHit
    if last and last.owner==owner and last.ownerState==owner.Character.State and last.environment==owner.EnvironmentId and last.ownerId==owner.ObjectId and last.model.Parent and args[1]:IsDescendantOf(last.model) then
        last.at=now;last.deadAt=nil;self._nextUpdate=0;return
    end
    local entry=self:_FromHitPart(args[1])
    if not entry then return end
    self._lastHit={model=entry.model,owner=owner,ownerId=owner.ObjectId,ownerState=owner.Character.State,environment=owner.EnvironmentId,at=now}
    self._nextUpdate=0
end
function Panel:_LastHit(now)
    local last=self._lastHit
    if not last then return nil end
    local owner=self:_Local()
    local duration=number(self:_Config().RecentHitDuration,3,.5,10)
    if owner~=last.owner or not owner.Character or owner.ObjectId~=last.ownerId or owner.EnvironmentId~=last.environment or owner.Character.State~=last.ownerState or not owner.Character.State.Alive
        or now<last.at or now-last.at>duration then self._lastHit=nil;return nil end
    local entry=self:_ReadModel(last.model,true,true)
    if not entry then self._lastHit=nil;return nil end
    if entry.hp<=0 then
        last.deadAt=last.deadAt or now
        if now-last.deadAt>.8 then self._lastHit=nil;return nil end
    else last.deadAt=nil end
    return entry
end
function Panel:_NativeOwner()
    local players=self._services.Players
    local player=players and players.LocalPlayer
    local fallback=self:_Local()
    local state=fallback and fallback.Character and fallback.Character.State
    local model=player and player.Character or (state and state.Model)
    if not model or not model.Parent then return nil end
    local humanoid=model:FindFirstChildOfClass("Humanoid")
    if humanoid then
        if not finite(humanoid.Health) or humanoid.Health<=0 then return nil end
    elseif not (state and state.Alive and state.Model==model) then return nil end
    local environment=player and player:GetAttribute("EnvironmentID")
    if environment==nil and not player and fallback then environment=fallback.EnvironmentId end
    return {model=model,player=player,environment=environment}
end
function Panel:_ReadDirect(model,allowDead,owner)
    if typeof(model)~="Instance" or not model:IsA("Model") or not model.Parent then return nil end
    owner=owner or self:_NativeOwner()
    if not owner or owner.model==model then return nil end
    local players=self._services.Players
    local player=players and players:GetPlayerFromCharacter(model)
    if player and (player==owner.player or not player.Parent or player.Character~=model or self:_IsTeammate(player)) then return nil end

    if player then
        local environment=player:GetAttribute("EnvironmentID")
        if owner.environment~=nil and environment~=nil and environment~=owner.environment then return nil end
    end
    local humanoid=model:FindFirstChildOfClass("Humanoid")
    if not humanoid then return nil end
    local hp,maximum=humanoid.Health,humanoid.MaxHealth
    if not finite(hp) or not finite(maximum) or maximum<=0 or hp<0 or (hp==0 and not allowDead) then return nil end
    local part=model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Head") or model.PrimaryPart
    return {model=model,state=humanoid,humanoid=humanoid,hp=math.clamp(hp,0,maximum),maximum=maximum,
        player=player,name=model.Name,part=part,direct=true}
end
function Panel:_ReadDirectPart(part,owner)
    if typeof(part)~="Instance" then return nil end
    local node=part
    for _=1,8 do
        if not node then break end
        if node:IsA("Model") then
            local entry=self:_ReadDirect(node,false,owner)
            if entry then return entry end
        end
        node=node.Parent
    end
end
function Panel:_DirectTarget(now)
    local owner=self:_NativeOwner()
    if not owner then self._directRetention=nil;self._nativeReason="local character unavailable";return nil end
    local camera=workspace.CurrentCamera
    if not camera then self._nativeReason="camera unavailable";return nil end
    local entry

    if RaycastParams and type(camera.ViewportPointToRay)=="function" and type(workspace.Raycast)=="function" then
        if not self._rayParams then
            self._rayParams=RaycastParams.new();self._rayParams.FilterType=Enum.RaycastFilterType.Exclude
            self._rayParams.IgnoreWater=true
        end
        if self._rayOwner~=owner.model or self._rayCamera~=camera then
            self._rayParams.FilterDescendantsInstances={owner.model,camera}
            self._rayOwner=owner.model;self._rayCamera=camera
        end
        local viewport=camera.ViewportSize
        local ray=camera:ViewportPointToRay(viewport.X*.5,viewport.Y*.5)
        local ok,hit=pcall(workspace.Raycast,workspace,ray.Origin,ray.Direction*4096,self._rayParams)
        if ok and hit then entry=self:_ReadDirectPart(hit.Instance,owner) end
        if not ok then self._nativeReason="world ray unavailable" end
    end

    local players=self._services.Players
    if not entry and players and type(players.GetPlayers)=="function" then
        local viewport=camera.ViewportSize
        local radius=number(self:_Config().CrosshairRadius,250,50,800)
        local score=radius*radius
        for i,player in players:GetPlayers() do
            if i>128 then break end
            if player~=owner.player then
                local candidate=self:_ReadDirect(player.Character,false,owner)
                local part=candidate and candidate.part
                local position=part and part.Parent and part.Position
                if position and finite(position.X) and finite(position.Y) and finite(position.Z) and math.max(math.abs(position.X),math.abs(position.Y),math.abs(position.Z))<1e6 then
                    local point,onScreen=camera:WorldToViewportPoint(position)
                    if onScreen and point.Z>0 and finite(point.X) and finite(point.Y) then
                        local distance=(point.X-viewport.X*.5)^2+(point.Y-viewport.Y*.5)^2
                        if distance<score then score=distance;entry=candidate end
                    end
                end
            end
        end
    end
    if entry then
        self._nativeReason="direct Humanoid health"
        self._directRetention={model=entry.model,humanoid=entry.humanoid,player=entry.player,owner=owner.model,environment=owner.environment,at=now}
        return entry
    end
    local held=self._directRetention
    if held and held.owner==owner.model and held.environment==owner.environment and now>=held.at
        and now-held.at<=number(self:_Config().RecentHitDuration,3,.5,10)
        and (not held.player or held.player.Character==held.model) then
        entry=self:_ReadDirect(held.model,true,owner)
        if entry and entry.humanoid==held.humanoid then
            if entry.hp<=0 then
                held.deadAt=held.deadAt or now
                if now-held.deadAt>.8 then entry=nil end
            end
            if entry then return entry end
        end
    end
    self._directRetention=nil;self._nativeReason="no Humanoid target under crosshair"
end
function Panel:Debug()
    local config=self:_Config()
    return string.format("target-hp enabled=%s source=%s state=%s native=%s context=%s",
        tostring(config.Enabled==true),"Automatic",self._status and self._status.Text or "not created",
        self._nativeReason or "not sampled",tostring(self:_Local()~=nil))
end
function Panel:_Current(now)
    local bot=self._context.HvhRagebot
    local at=bot and bot._wraithHudUpdatedAt
    if bot and bot._enabled and finite(at) and now>=at and now-at<.7 then
        local target=bot._wraithHudTarget
        local entry=self:_ReadFighter(target and target.FighterState)
        if entry and entry.state==target.AliveState then return entry end
    end
    local silent=self._context.SilentAim
    if silent and silent._active then
        local entry=self:_ReadFighter(silent._currentTarget)
        if entry then return entry end
    end
    local aim=self._context.Aimbot
    local fighters=self._context.HvhFighters
    local part=aim and aim._active and aim._lastHitbox
    if part and fighters and fighters.StateByModel then
        local node=part
        for _=1,6 do
            if not node then break end
            local entry=self:_ReadFighter(fighters.StateByModel[node])
            if entry then return entry end
            node=node.Parent
        end
    end
    return nil
end
function Panel:_Crosshair()
    local fighters=self._context.HvhFighters
    local camera=workspace.CurrentCamera
    if not camera then return nil end
    local viewport=camera.ViewportSize
    local radius=number(self:_Config().CrosshairRadius,250,50,800)
    local best,score=nil,radius*radius
    for _,fighter in (fighters and fighters.EnemyByPlayer or {}) do
        local entry=self:_ReadFighter(fighter)
        if entry then
            local part=entry.state.HitboxHead or entry.state.RootPart
            local position=part and part.Parent and part.Position
            if position and finite(position.X) and finite(position.Y) and finite(position.Z) and math.max(math.abs(position.X),math.abs(position.Y),math.abs(position.Z))<1e6 then
                local point,onScreen=camera:WorldToViewportPoint(position)
                if onScreen and point.Z>0 and finite(point.X) and finite(point.Y) then
                    local distance=(point.X-viewport.X*.5)^2+(point.Y-viewport.Y*.5)^2
                    if distance<score then best=entry;score=distance end
                end
            end
        end
    end

    local registry=self._context.TargetHealthEnemies
    for i,model in (registry and registry.Dummies or {}) do
        if i>128 then break end
        local entry=self:_ReadModel(model,false,false)
        local part=entry and entry.part
        if part and part.Parent then
            local position=part.Position
            if finite(position.X) and finite(position.Y) and finite(position.Z) and math.max(math.abs(position.X),math.abs(position.Y),math.abs(position.Z))<1e6 then
                local point,onScreen=camera:WorldToViewportPoint(position)
                if onScreen and point.Z>0 and finite(point.X) and finite(point.Y) then
                    local distance=(point.X-viewport.X*.5)^2+(point.Y-viewport.Y*.5)^2
                    if distance<score then best=entry;score=distance end
                end
            end
        end
    end
    return best
end
function Panel:_Preview()
    local tab=self._visuals
    return self:_Config().Preview==true and self._menu.Visible==true and tab and tab._window.ActiveTab==tab
        and tab.ActivePage and tab.ActivePage.Label=="Player ESP"
end
function Panel:_PaintBar(ratio,waiting,instant)
    local config=self:_Config()
    local mode=config.BarColorMode or "Health"
    local tint
    if waiting then tint=Color3.fromRGB(122,126,138)
    elseif mode=="Menu Accent" then tint=color(self._theme.get("Accent"),color(config.BarColor,WHITE))
    elseif mode=="Custom" then tint=color(config.BarColor,WHITE)
    else tint=Panel.HealthColor(ratio,config) end
    if self._ratio==ratio and self._barTint==tint and self._waiting==waiting and not instant then return end
    self._status.TextColor3=tint
    if self._barTween then self._barTween:Cancel();self._barTween=nil end
    local properties={Size=UDim2.fromScale(ratio,1),BackgroundColor3=tint}
    if not instant and self._root.Visible then
        self._barTween=self._services.TweenService:Create(self._bar,TweenInfo.new(.12,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),properties)
        self._barTween:Play()
    else
        self._bar.Size=properties.Size;self._bar.BackgroundColor3=tint
    end
    self._barTint=tint
end
local function coordinate(value)
    if math.abs(value)>=10000 then return string.format("%.2g",value) end
    local rounded=math.round(value*10)/10
    return string.format("%.1f",rounded==0 and 0 or rounded)
end
function Panel:_Coordinates(entry,preview)
    local position
    if entry and not preview then
        local state=type(entry.state)=="table" and entry.state or nil
        local model=entry.model or state and state.Model or entry.player and entry.player.Character
        local part=state and state.RootPart
        if not part and model then part=model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart end
        part=part or entry.part or state and state.HitboxHead
        if part and part.Parent and part:IsA("BasePart") then position=part.Position end
    end
    local text="X: --  Y: --  Z: --"
    if typeof(position)=="Vector3" and finite(position.X) and finite(position.Y) and finite(position.Z) then
        text=string.format("X: %s  Y: %s  Z: %s",coordinate(position.X),coordinate(position.Y),coordinate(position.Z))
    end
    if self._position.Text~=text then self._position.Text=text end
end
function Panel:_SetEntry(entry,preview)
    local config=self:_Config()
    self:_Coordinates(entry,preview)
    local player=entry.player
    local settings=self._store.Data.Esp.Settings or {}
    local name=preview and "Wraith.cc" or (player and (settings.UseDisplayName and player.DisplayName or player.Name)) or entry.name or "Target"
    if type(name)~="string" or name=="" then name="Target" end
    name=name:gsub("%c","")
    local hp,maximum=entry.hp,entry.maximum
    local health
    if config.HealthFormat=="Percent" then health=string.format("%d%% HP",math.floor(hp/maximum*100+.5))
    elseif config.HealthFormat=="HP" then health=string.format("%d HP",math.ceil(hp))
    else health=string.format("%d / %d HP",math.ceil(hp),math.ceil(maximum)) end
    if self._name.Text~=name then self._name.Text=name end
