local Trove=tbl17.k()
local TweenService=tbl17.t().TweenService
local Motion={}
local ORANGE=Color3.fromRGB(255,142,18)
local function controller(trove)
    local self={tweens={},destroyed=false}
    function self:Cancel(key)
        local tween=self.tweens[key]
        if tween then self.tweens[key]=nil;tween:Cancel();tween:Destroy() end
    end
    function self:Play(key,node,seconds,goal,immediate,style)
        if self.destroyed then return end
        self:Cancel(key)
        if immediate then
            for property,value in goal do if node[property]~=value then node[property]=value end end
        else
            local tween=TweenService:Create(node,TweenInfo.new(seconds,style or Enum.EasingStyle.Quint,Enum.EasingDirection.Out),goal)
            self.tweens[key]=tween
            tween.Completed:Once(function()
                if self.tweens[key]==tween then self.tweens[key]=nil end
                task.defer(function() tween:Destroy() end)
            end)
            tween:Play()
        end
    end
    function self:Destroy()
        if self.destroyed then return end
        self.destroyed=true
        for key in self.tweens do self:Cancel(key) end
    end
    trove:Add(function() self:Destroy() end)
    return self
end
local function visible(node)
    while node do
        if node:IsA("GuiObject") and not node.Visible then return false end
        node=node.Parent
    end
    return true
end
function Motion.Button(trove,button,icon,menu)
    if not icon then return nil end
    local self=controller(trove)
