    self.hovered=false;self.pressed=false;self.selected=false
    function self:Refresh(immediate)
        local amount=self.pressed and .91 or (self.hovered and 1.13 or (self.selected and 1.04 or 1))
        local angle=self.pressed and -4 or (self.hovered and 5 or 0)
        self:Play("scale",scale,self.pressed and .09 or .21,{Scale=amount},immediate)
        self:Play("rotation",icon,.21,{Rotation=angle},immediate)
    end
    function self:SetSelected(selected)
        if self.selected==selected then return end
        self.selected=selected;self:Refresh(not menu.Visible)
    end
    trove:Connect(button.MouseEnter,function() self.hovered=true;self:Refresh() end)
    trove:Connect(button.MouseLeave,function() self.hovered=false;self.pressed=false;self:Refresh() end)
    local function pointer(input)
        return input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch
    end
    tbl17.x().connectPress(trove,button,function() self.pressed=true;self:Refresh() end,function() self.pressed=false;self:Refresh() end)
    trove:Connect(menu.VisibilityChanged,function(open)
        if not open then self.hovered=false;self.pressed=false;self:Refresh(true) end
    end)
