end
function Motion.Control(trove,hit,visual,menu,options)
    options=options or {}
    local self=controller(trove)
    local scale=trove:Add(Instance.new("UIScale"))
    scale.Name="wraith"..(options.Name or "Control").."Motion"
    scale.Scale=1;scale.Parent=visual
    self.hovered=false;self.pressed=false;self.open=false
    local baseAngle=visual.Rotation
    local function amount()
        return self.pressed and (options.PressScale or .9) or (self.hovered and (options.HoverScale or 1.12) or 1)
    end
    function self:Refresh(immediate,bounce)
        immediate=immediate or not menu.Visible or not visible(hit)
        self:Play("scale",scale,bounce and .24 or .16,{Scale=amount()},immediate,bounce and Enum.EasingStyle.Back or nil)
        if options.HoverAngle then
            self:Play("rotation",visual,.22,{Rotation=baseAngle+(self.open and 180 or 0)+(self.hovered and options.HoverAngle or 0)},immediate)
        end
    end
    function self:SetOpen(open)
        self.open=open==true;self:Refresh()
    end
    function self:SetPressed(pressed)
        local release=self.pressed and not pressed
        self.pressed=pressed==true;self:Refresh(false,release)
    end
    function self:Pulse(force)

        if not menu.Visible or not visible(hit) or not (force or self.hovered or self.pressed) then return end
        self:Cancel("scale");scale.Scale=amount()*.84
        self:Refresh(false,true)
    end
    trove:Connect(hit.MouseEnter,function() self.hovered=true;self:Refresh() end)
    trove:Connect(hit.MouseLeave,function()
        self.hovered=false
        if not options.ExternalPress then self.pressed=false end
        self:Refresh()
    end)
    if not options.ExternalPress then
        local function pointer(input)
            return input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch
        end
        tbl17.x().connectPress(trove,hit,function() self:SetPressed(true) end,function() self:SetPressed(false) end)
    end
    local function reset()
        if not self.hovered and not self.pressed and next(self.tweens)==nil then return end
        self.hovered=false;self.pressed=false;self:Refresh(true)
    end
    trove:Connect(menu.VisibilityChanged,function(open) if not open then reset() end end)
    trove:Connect(hit:GetPropertyChangedSignal("Visible"),function() if not hit.Visible then reset() end end)
    return self
end

function Motion.Popup(trove,menu,root)
    local self=controller(trove)
    local driver=trove:Add(Instance.new("NumberValue"))
    driver.Value=0
    self.open=false;self.position=root.Position;self.epoch=0
    function self:Apply(value)
        local position=self.position
        root.GroupTransparency=1-value
        root.Position=UDim2.new(position.X.Scale,position.X.Offset,position.Y.Scale,position.Y.Offset+10*(1-value))
    end
    function self:CancelFinish()
        if self.finish then self.finish:Disconnect();self.finish=nil end
    end
    function self:SetPosition(position)
        self.position=position;self:Apply(driver.Value)
    end
    function self:SetOpen(open,position)
        if self.destroyed then return end
        self.epoch+=1
        local epoch=self.epoch
        self:CancelFinish();self:Cancel("popup")
        self.open=open==true
        if position then self.position=position end
        local target=self.open and 1 or 0
        if not menu.Visible then
            driver.Value=0;self:Apply(0);root.Visible=false;return
        end
        if self.open then root.Visible=true end
        self:Apply(driver.Value)
        if math.abs(driver.Value-target)<.001 then
            driver.Value=target;self:Apply(target);root.Visible=self.open;return
        end
        self:Play("popup",driver,self.open and .26 or .16,{Value=target})
        local tween=self.tweens.popup
        self.finish=tween.Completed:Connect(function()
            if self.destroyed or self.epoch~=epoch then return end
            self:CancelFinish()
            driver.Value=target;self:Apply(target);root.Visible=self.open
        end)
    end
    trove:Connect(driver.Changed,function(value) self:Apply(value) end)
    trove:Connect(menu.VisibilityChanged,function(open)
        if open then
            if self.open then self:SetOpen(true) end
        else
            self.epoch+=1;self:CancelFinish();self:Cancel("popup")
            driver.Value=0;self:Apply(0);root.Visible=false
        end
    end)
    trove:Add(function() self.epoch+=1;self:CancelFinish() end)
    return self
end
function Motion.Track(trove,hit,track,menu,batch)
    local self=controller(trove)
    local glow=trove:Add(Instance.new("Frame"))
    glow.Name="wraithSliderActivity";glow.BorderSizePixel=0;glow.BackgroundTransparency=1
    glow.Active=false;glow.Selectable=false;glow.ZIndex=track.ZIndex
