function Motion.Reveal(menu,page)
    local trove=Trove.new("ui.PageReveal")
    local self=controller(trove)
    local shown=false
    local basePosition=page.Position
    local function refresh()
        local show=menu.Visible and visible(page)
        if shown==show then return end
        shown=show
        self:Cancel("reveal")
        if show then
            basePosition=page.Position
            page.Position=UDim2.new(basePosition.X.Scale,basePosition.X.Offset,basePosition.Y.Scale,basePosition.Y.Offset+6)
            self:Play("reveal",page,.18,{Position=basePosition})
        elseif page.Position~=basePosition then page.Position=basePosition end
    end
    local node=page
    while node and node:IsA("GuiObject") do
        trove:Connect(node:GetPropertyChangedSignal("Visible"),refresh)
        node=node.Parent
    end
    trove:Connect(menu.VisibilityChanged,refresh)
    refresh()
    return {Destroy=function() trove:Destroy() end}
end

function Motion.Window(menu,frame)
    local trove=Trove.new("ui.OrangeOuterGlow")
    local self=controller(trove)
    local root=trove:Add(Instance.new("Frame"))
    root.Name="wraithOrangeGlow";root.BackgroundTransparency=1;root.BorderSizePixel=0
    root.Active=false;root.Selectable=false;root.ClipsDescendants=false
    root.ZIndex=math.max(0,frame.ZIndex-1)
    local driver=trove:Add(Instance.new("NumberValue"))
    driver.Value=0
    local strokes={}

    local rings=tbl17.u().IsMobile() and {{16,.045},{6,.12},{1.2,.9}} or {{34,.018},{25,.026},{18,.038},{12,.058},{7,.09},{3,.15},{1.2,.9}}
    for _,spec in rings do
        local ring=Instance.new("Frame")
        ring.Name="wraithOrangeGlowRing";ring.BackgroundTransparency=1;ring.BorderSizePixel=0
        ring.Active=false;ring.Selectable=false;ring.Size=UDim2.fromScale(1,1)
        ring.ZIndex=root.ZIndex;ring.Parent=root
        local corner=Instance.new("UICorner");corner.CornerRadius=UDim.new(0,6);corner.Parent=ring
        local stroke=Instance.new("UIStroke")
        stroke.Name="wraithOrangeGlowStroke";stroke.Color=ORANGE
        stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
        stroke.Thickness=spec[1];stroke.Transparency=1;stroke.Parent=ring
        table.insert(strokes,{stroke,spec[2]})
    end
    local function align()
        root.AnchorPoint=frame.AnchorPoint;root.Position=frame.Position;root.Size=frame.Size
    end
    align();root.Visible=false;root.Parent=frame.Parent
    for _,property in {"AnchorPoint","Position","Size"} do
        trove:Connect(frame:GetPropertyChangedSignal(property),align)
    end
    local sourceScale=frame:FindFirstChildOfClass("UIScale")
    if sourceScale then
        local scale=Instance.new("UIScale");scale.Scale=sourceScale.Scale;scale.Parent=root
        trove:Connect(sourceScale:GetPropertyChangedSignal("Scale"),function() scale.Scale=sourceScale.Scale end)
    end
    trove:Connect(driver.Changed,function(value)
        for _,spec in strokes do spec[1].Transparency=1-spec[2]*value end
    end)
