local function fn35()
local Anchor={}
local states=setmetatable({},{__mode="k"})
local models=setmetatable({},{__mode="k"})
local function finite(value) return type(value)=="number" and value==value and math.abs(value)<1e8 end
local function number(value,fallback,minimum,maximum)
    return finite(value) and math.clamp(value,minimum,maximum) or fallback
end
function Anchor.Defaults(withText)
    local value={Enabled=false,OffsetX=0,OffsetY=-8,Smoothing=0}
    if withText then value.Mode="Crosshair" end
    return value
end
function Anchor.Controls(section,path,withText)
    local function at(key) local out=table.clone(path);table.insert(out,key);return out end
    local group=section:AddGroup({Source=section:AddToggle({Label="Follow Weapon",Config=at("Enabled")})})
    if withText then group:AddDropdown({Label="Follow Weapon Mode",Options={"Crosshair","Crosshair + Text"},Config=at("Mode")}) end
    group:AddSlider({Label="Weapon Horizontal Offset",Min=-200,Max=200,Step=1,Config=at("OffsetX")})
    group:AddSlider({Label="Weapon Vertical Offset",Min=-200,Max=200,Step=1,Config=at("OffsetY")})
    group:AddSlider({Label="Weapon Follow Smoothing",Min=0,Max=40,Step=1,Tooltip="0 follows weapon motion directly",Config=at("Smoothing")})
end
local function normalized(value)
    return type(value)=="string" and value:lower():gsub("[^a-z]","") or ""
end
local armNames={arm=true,arms=true,hand=true,hands=true,leftarm=true,rightarm=true,lefthand=true,righthand=true,
    leftupperarm=true,rightupperarm=true,leftlowerarm=true,rightlowerarm=true,leftglove=true,rightglove=true,
    gloves=true,leftsleeve=true,rightsleeve=true,sleeves=true}
local itemNames={itemmodel=true,itemvisual=true,item=true,leftitem=true,rightitem=true,weapon=true,gun=true,
    weaponmodel=true,weaponvisual=true,firearm=true,fists=true}
local markerNames={muzzleattachment=300,muzzle=290,muzzlepoint=285,firepoint=280,barrelend=275,
    bladetip=270,tipattachment=265,tip=260}
local helperNames={camera=true,humanoidrootpart=true,rootpart=true,root=true,aimpoint=true,aim=true}
local function skipped(name)
    return helperNames[name] or name:find("charm",1,true) or name:find("effect",1,true)
        or name:find("particle",1,true) or name:find("wraith",1,true)
end
local meleeNames={fists=true,daggers=true,knife=true,katana=true,scythe=true,chainsaw=true,riotshield=true,battleaxe=true,sword=true,axe=true}
local function itemKind(item,equipped)
    local info=item.Info
    if equipped.__type=="Melee" or equipped.Type=="MeleeView"
        or type(info)=="table" and info.Type=="Melee" or meleeNames[normalized(item.Name)]==true then return "Melee" end
    if equipped.Index==4 or equipped.__type=="Throwable" or equipped.__type=="Custom"
        or equipped.Type=="ThrowableView" or equipped.Type=="CustomView"
        or type(info)=="table" and (info.Type=="Throwable" or info.Type=="Custom") then return "Utility" end
    return "Gun"
end
local function collect(view,item,model,now,kind)
    local nativeArms,nativeItems,nativeSides={},{},{}
    for _,key in {"LeftArm","RightArm","LeftHand","RightHand","ArmsModel"} do
        local object=rawget(view,key)
        if typeof(object)=="Instance" and object~=model then
            nativeArms[object]=true
            if key:sub(1,4)=="Left" then nativeSides[object]="Left"
            elseif key:sub(1,5)=="Right" then nativeSides[object]="Right" end
        end
    end
    for _,key in {"ItemModel","WeaponModel"} do
        local object=rawget(view,key)
        if typeof(object)=="Instance" and object~=model then nativeItems[object]=true end
    end
    local record={model=model,kind=kind,handheld=kind~="Gun",paired=normalized(item.Name)=="fists" or normalized(item.Name)=="daggers",
        candidates={},hands={},time=now}
    local examined=0
    local function scan(node,inArm,inItem,side)
        for _,child in node:GetChildren() do
            examined+=1
            if examined>512 then return end
            local name=normalized(child.Name)
            if skipped(name) then continue end
            local arm,weapon=inArm,inItem
            if weapon or nativeItems[child] or itemNames[name] then arm=false;weapon=true
            elseif nativeArms[child] or armNames[name] then arm=true end
            local branch=nativeSides[child] or side
            if nativeSides[child] then
            elseif name:find("left",1,true) then branch="Left"
            elseif name:find("right",1,true) then branch="Right" end
            local score=markerNames[name]
            if kind~="Gun" and (name:find("muzzle",1,true) or name=="firepoint" or name=="barrelend") then continue end
            if child:IsA("Attachment") and score and not arm then
                table.insert(record.candidates,{object=child,score=score,side=branch})
            elseif child:IsA("BasePart") then
                local size=child.Size
                if finite(size.X) and finite(size.Y) and finite(size.Z)
                    and math.max(size.X,size.Y,size.Z)<=32 then
                    local visible=child.Transparency<1 or child:IsA("MeshPart")
                    if visible then
                        local rank=score or (name:find("barrel",1,true) and 180)
                            or (name:find("blade",1,true) and 170)
                            or (name:find("shield",1,true) and 150)
                            or (name:find("handle",1,true) and 120)
                            or (name:find("grip",1,true) and 110)
                            or 30+math.min(30,size.X*size.Y*size.Z)
                        local entry={object=child,score=rank,side=branch}
                        if arm then
                            if name:find("hand",1,true) or name:find("glove",1,true)
                                or child==rawget(view,"LeftHand") or child==rawget(view,"RightHand") then entry.score=220
                            elseif name:find("lowerarm",1,true) then entry.score=100
                            else entry.score=70 end
                            table.insert(record.hands,entry)
                        else table.insert(record.candidates,entry) end
                    end
                end
            end
            scan(child,arm,weapon,branch)
        end
    end
    scan(model,false,false,nil)
    if #record.candidates==0 then
        local rankBySide={}
        for _,entry in record.hands do
            local side=entry.side or "Unknown"
            rankBySide[side]=math.max(rankBySide[side] or 0,entry.score)
        end
        for _,entry in record.hands do
            if entry.score==rankBySide[entry.side or "Unknown"] then table.insert(record.candidates,entry) end
        end
    end
    record.hands=nil
    table.sort(record.candidates,function(a,b)
        if kind~="Gun" then
            local ap=a.side=="Right" and 2 or a.side==nil and 1 or 0
            local bp=b.side=="Right" and 2 or b.side==nil and 1 or 0
            if ap~=bp then return ap>bp end
        end
        return a.score>b.score
    end)
    while #record.candidates>12 do table.remove(record.candidates) end
    models[view]=record
    return record
end
local function project(camera,point,keepOnScreen)
    if typeof(point)=="CFrame" then point=point.Position end
    if typeof(point)~="Vector3" or not finite(point.X) or not finite(point.Y) or not finite(point.Z) then return nil end
    local projected,onScreen=camera:WorldToViewportPoint(point)
    if not finite(projected.X) or not finite(projected.Y) or not finite(projected.Z) or projected.Z<=.01 then return nil end
    if keepOnScreen then
        local viewport=camera.ViewportSize
        return Vector2.new(math.clamp(projected.X,4,math.max(4,viewport.X-4)),math.clamp(projected.Y,4,math.max(4,viewport.Y-4)))
    end
    if not onScreen then return nil end
    return Vector2.new(projected.X,projected.Y)
end
local function partPoint(object,camera,tip)
    if object:IsA("Attachment") then return object.WorldPosition end
    local frame,size=object.CFrame,object.Size
    local up=camera.CFrame.UpVector
    if tip then

        local axis= size.Y>=size.X and size.Y>=size.Z and Vector3.new(0,size.Y*.5,0)
            or size.X>=size.Z and Vector3.new(size.X*.5,0,0) or Vector3.new(0,0,size.Z*.5)
        local a=project(camera,frame:PointToWorldSpace(axis),true)
        local b=project(camera,frame:PointToWorldSpace(-axis),true)
        if a and b and math.abs(a.Y-b.Y)>1 then
            return frame:PointToWorldSpace(a.Y<b.Y and axis or -axis)
        end
    end

    local halfHeight=(math.abs(frame.RightVector:Dot(up))*size.X
        +math.abs(frame.UpVector:Dot(up))*size.Y
        +math.abs(frame.LookVector:Dot(up))*size.Z)*.5
    return frame.Position+up*halfHeight
end
local function fromRecord(record,camera)
    local right,unmarked=false,false
    local leftX,rightX
    if record.handheld then
        for _,entry in record.candidates do
            local object=entry.object
            if object.Parent and object:IsDescendantOf(record.model) then
                if entry.side=="Right" then right=true elseif entry.side==nil then unmarked=true end
                if record.paired and entry.side==nil then
                    local center=project(camera,object:IsA("Attachment") and object.WorldPosition or object.Position,true)
                    if center then
                        leftX=leftX and math.min(leftX,center.X) or center.X
                        rightX=rightX and math.max(rightX,center.X) or center.X
                    end
                end
            end
        end
    end
    local best,bestRank,bestMarked
    for _,entry in record.candidates do
        local object=entry.object
        local selected=not record.handheld or (right and entry.side=="Right")
            or (not right and (not unmarked or entry.side==nil))
        if selected and object.Parent and object:IsDescendantOf(record.model) then
            if record.paired and not right and unmarked and leftX and rightX then
                local center=project(camera,object:IsA("Attachment") and object.WorldPosition or object.Position,true)
                if not center or center.X<(leftX+rightX)*.5 then continue end
            end
            local point=project(camera,partPoint(object,camera,record.handheld),record.handheld)
            if point then
                if not record.handheld then return point end

                local marked=entry.score>=260
                if not best or marked and not bestMarked or marked==bestMarked and (point.Y<best.Y-.5 or math.abs(point.Y-best.Y)<=.5
                    and (entry.score>bestRank or entry.score==bestRank and point.X>best.X)) then
                    best=point;bestRank=entry.score;bestMarked=marked
                end
            end
        end
    end
    return best
end

local function fallback(view,item,camera,kind)
    local model=rawget(view,"Model")
    if typeof(model)~="Instance" or not model.Parent then return nil end
    local now=os.clock()
    local record=models[view]
    if not record or record.model~=model or record.kind~=kind or now-record.time>2 then
        record=collect(view,item,model,now,kind)
    end
    local point=fromRecord(record,camera)
    if not point and now-record.time>.25 then point=fromRecord(collect(view,item,model,now,kind),camera) end
    return point
end
local function sample(context)
    local camera=workspace.CurrentCamera
    local inner=context and context.Inner
    local behaviors=inner and inner.ItemBehaviors
    local equipped=behaviors and behaviors:GetEquipped()
    local item=equipped and equipped.Inner
    local view=type(item)=="table" and rawget(item,"ViewModel")
    if not camera or type(view)~="table" then return nil end
    local model=rawget(view,"Model")
    if typeof(model)=="Instance" and not model.Parent then return nil end
    local kind=itemKind(item,equipped)
    local point
    local method=view.GetMuzzlePosition
    if kind=="Gun" and type(method)=="function" then
        local ok,value=pcall(tbl17.b3(),method,view)
        if ok then point=project(camera,value) end
    end

    point=point or fallback(view,item,camera,kind)
    if not point then return nil end
    return point,view,camera
end
function Anchor.HasEquipped(context)
    local ok,available=pcall(function()
        if not tbl17.k14().IsPlaying() then return false end
        local inner=context and context.Inner
        local fighter=inner and inner.FighterState
        if not fighter or fighter.EnvironmentId==nil then return false end
        local state=fighter.Character and fighter.Character.State
