function Modes.NewUnderground(store,player)
    local v115 = store
    local cache = { Position = nil, RetryAt = 0, Params = nil }
    local localPlayer = player or cloneref(game:GetService("Players")).LocalPlayer

    return { compute = function(clientCFrame)
        local now = os.clock()
        local underground = v115.Data.Ragebot.Evasion.Underground
        local depth = number(tonumber(underground and underground.Depth),10,5,14)

        if cache.Position and now < cache.RetryAt then
            return cache.Position
        end

        if not cache.Params then
