  local yDist=number(tonumber(config and config.YDistance),100,100,10000000)
  local cooldown=number(tonumber(config and config.Cooldown),.2,0,1)
  if not cache.Started then cache.Started=true;cache.LastTeleport=now;cache.YOffset=yDist end
  if now>=cache.LastTeleport+cooldown then cache.YOffset+=yDist;cache.LastTeleport=now end
  if cache.YOffset>10000000 then cache.YOffset=10000000 end
  return clientCFrame+Vector3.new(0,cache.YOffset,0)
 end
 function self.Reset() cache.YOffset=0;cache.LastTeleport=0;cache.Started=false end
