end
function Modes.NewCounter(player)
 local players={LocalPlayer=player}
 local config=Modes.CounterDefaults()
 local K2={t0=0,boostAt=0,fly=Vector3.zero,stop=nil,stopIdx=-1,spawn=nil,list={},last=nil,listReady=false}
 local function cfg(name) return config[name] end

local function cycleTimes()
local cycle = math.max(cfg("KiciaCycleMs") or 50, 5) / 1000
local fly = math.min((cfg("KiciaFlyMs") or 25) / 1000, cycle * 0.95)
return cycle, fly
end
local function buildSpawnList(spawn)
K2.spawn = spawn K2.list = {} K2.listReady = true
local depth = cfg("KiciaDepth") or 6
local radius = cfg("KiciaRadius") or 30
local rng = Random.new()
local params = RaycastParams.new()
params.FilterType = Enum.RaycastFilterType.Exclude
local char = players.LocalPlayer.Character
if char then params.FilterDescendantsInstances = { char } end
for _ = 1, 60 do
if #K2.list >= 16 then break end
local angle = rng:NextNumber(0, math.pi * 2)
local dist = rng:NextNumber(4, math.max(radius, 5))
local origin = spawn + Vector3.new(math.cos(angle) * dist, 8, math.sin(angle) * dist)
local hit = workspace:Raycast(origin, Vector3.new(0, -30, 0), params)
if hit and hit.Normal.Y > 0.7 then
K2.list[#K2.list + 1] = hit.Position - Vector3.new(0, depth, 0)
end
end
end
local function resolveStopPos(mode, spawn)
local fallback = spawn - Vector3.new(0, cfg("KiciaDepth") or 6, 0)
if mode ~= "Solix counter" then return fallback end
if K2.spawn ~= spawn or not K2.listReady then buildSpawnList(spawn) end
local n = #K2.list
if n == 0 then return fallback end
local idx = math.random(1, n)
if n > 1 and idx == K2.last then idx = idx % n + 1 end
K2.last = idx
return K2.list[idx]
end
local function kiciaSolixInit(root, now)
K2.t0 = now K2.boostAt = now
K2.spawn = root.Position K2.fly = root.Position
K2.stop, K2.stopIdx = nil, -1
K2.list = {} K2.listReady = false K2.last = nil
end
local function kiciaSolixStep(mode, root, dt)
local now = os.clock()
local t = now - K2.t0
local cycle, flyWindow = cycleTimes()
local flying = (t % cycle) < flyWindow
if now >= K2.boostAt then
if flying then K2.fly += Vector3.new(0, cfg("KiciaBoost") or 100000, 0) end
K2.boostAt = now + (cfg("KiciaBoostMs") or 600) / 1000
end
if not flying then
local idx = math.floor(t / cycle)
if idx ~= K2.stopIdx or not K2.stop then
K2.stopIdx = idx K2.stop = resolveStopPos(mode, K2.spawn)
end
root.CFrame = CFrame.new(K2.stop) * CFrame.Angles(math.pi / 2, 0, 0)
else
local zig = math.cos(t * (cfg("KiciaZigFreq") or 8)) * (cfg("KiciaZigAmp") or 400) * dt
K2.fly += Vector3.new(zig, (cfg("KiciaFlySpeed") or 15000) * dt, 0)
root.CFrame = CFrame.new(K2.fly) * CFrame.Angles(-math.pi / 2, 0, 0)
end
root.AssemblyLinearVelocity = Vector3.zero
end

 local started,previousMode=false,nil
 local proxy={}
 local self={}
 function self.Reset() started=false;previousMode=nil;K2.list={};K2.listReady=false;K2.last=nil end
 function self.Compute(mode,cf,dt,settings)
  config=settings
  proxy.Position=cf.Position;proxy.CFrame=cf
  if not started or mode~=previousMode then kiciaSolixInit(proxy,os.clock());started=true;previousMode=mode end
  kiciaSolixStep(mode,proxy,number(dt,1/60,0,.1))


  return proxy.CFrame
 end
 return self
end
function Modes.BuildCounterControls(grid)
 local function addCounter(key,title,side)
  local s=grid:AddSection({Title=title,Side=side})
  local function path(name) return {"Counters",key,name} end
  s:AddToggle({Label=key.." Counter",Tooltip="Enable this counter. The most recently enabled counter controls movement.",Config=path("Enabled")})
  for _,spec in {
   {"Cycle (ms)","KiciaCycleMs",5,500,1},{"Fly Window (ms)","KiciaFlyMs",1,500,1},
   {"Fly Speed","KiciaFlySpeed",100,50000,100},{"Boost","KiciaBoost",0,1000000,1000},
   {"Boost Interval (ms)","KiciaBoostMs",1,10000,1},{"Zigzag Amplitude","KiciaZigAmp",0,10000,1},
   {"Zigzag Frequency","KiciaZigFreq",0,50,.1},{"Depth","KiciaDepth",0,30,.5}
  } do s:AddSlider({Label=spec[1],Min=spec[3],Max=spec[4],Step=spec[5],Config=path(spec[2])}) end
  if key=="Solix" then s:AddSlider({Label="Spawn Radius",Min=5,Max=500,Step=1,Config=path("KiciaRadius")}) end
  s:AddToggle({Label="Yield During Attacks",Config=path("YieldDuringAttacks")})
 end
 addCounter("Kicia","Kicia Counter","right")
 addCounter("Solix","Solix Counter","left")
end

return Modes
end
