end
function Counter:_ActiveSettings() return self.configs[self.active or "UE"] end
function Counter:Sync(saved)
 if self.destroyed then return end
 saved=type(saved)=="table" and saved or {}
 local raw=type(saved.UE)=="table" and saved.UE or {}
 local settings={Enabled=raw.Enabled==true,TeleportDelay=number(raw.TeleportDelay,.2,.02,3),
  YDistance=number(raw.YDistance,500,100,1000),MaxRise=number(raw.MaxRise,10000,1000,100000),YieldDuringAttacks=raw.YieldDuringAttacks~=false}
 local configs={UE=settings,Kicia=Modes.CounterSettings(saved,"Kicia"),Solix=Modes.CounterSettings(saved,"Solix")}
 local active=self.active

 for _,key in {"UE","Kicia","Solix"} do
  if configs[key].Enabled and (not self.configs or not self.configs[key].Enabled) then active=key end
 end
 if not active or not configs[active].Enabled then
  active=nil
  for _,key in {"UE","Kicia","Solix"} do if configs[key].Enabled then active=key end end
 end
 local changed=active~=self.active
 if not changed and active and active~="UE" and self.configs then
  for key,value in configs[active] do if self.configs[active][key]~=value then changed=true;break end end
 end
 if changed or not active then self:_Reset() end
 if self.settings and (self.settings.TeleportDelay~=settings.TeleportDelay or self.settings.YDistance~=settings.YDistance
  or self.settings.MaxRise~=settings.MaxRise) then self.nextAt=0 end
