function Counter.Build(context,grid)
 local section=grid:AddSection({Title="UE Counter",Side="left"})
 section:AddToggle({Label="UE Counter",Tooltip="Repeated upward position changes based on the supplied counter.",Config={"Counters","UE","Enabled"}})
 section:AddSlider({Label="Teleport Delay (s)",Min=.02,Max=3,Step=.01,Config={"Counters","UE","TeleportDelay"}})
 section:AddSlider({Label="Y Distance",Min=100,Max=1000,Step=1,Config={"Counters","UE","YDistance"}})
