        mp = MusicPlayer or (shared and shared.MeowMusicPlayer)
    end
    if mp and mp.MainFrame then
        mp.MainFrame.Visible = v and true or false
        mp.Visible = mp.MainFrame.Visible
        if mp.Gui then mp.Gui.Enabled = true end
        if flags then flags.show_music_player = mp.MainFrame.Visible end
    else
