    if typeof(color) ~= "Color3" then return end
    MP_ACCENT = color
    for _, p in ipairs(MP_ACCENT_PARTS) do
        pcall(function() p.inst[p.prop] = color end)
    end
    local rf = getgenv and getgenv().MP_REFRESH_MODES
    if rf then pcall(rf) end
end

