shared.MeowMusicPlayer = MusicPlayer

local function initMusicPlayer()
    if MusicPlayer.Version == 4 and MusicPlayer.Gui and MusicPlayer.Gui.Parent and
       MusicPlayer.MainFrame and MusicPlayer.MainFrame.Parent then
        MusicPlayer.Gui.Enabled = true
        return MusicPlayer
    end
    if MusicPlayer.Gui then pcall(function() MusicPlayer.Gui:Destroy() end) end

    local coreGui
    if type(gethui) == "function" then
        local ok, result = pcall(gethui)
        if ok then coreGui = result end
    end
    coreGui = coreGui or game:GetService("CoreGui")
    local soundService = cloneref and cloneref(game:GetService("SoundService")) or game:GetService("SoundService")

    local sound = MusicPlayer.Sound
    if not sound or not sound.Parent then
        sound = soundService:FindFirstChild("_MeowMusicTrack")
    end
    if not sound or not sound:IsA("Sound") then
        sound = Instance.new("Sound")
        sound.Name = "_MeowMusicTrack"
        sound.Parent = soundService
    end
    sound.Volume = MusicPlayer.Volume
    sound.Looped = not MusicPlayer.RepeatAll
    MusicPlayer.Sound = sound

    local eq = MusicPlayer.Equalizer
    if not eq or not eq.Parent then
        eq = sound:FindFirstChild("_MeowBassBoost")
    end
    if not eq or not eq:IsA("EqualizerSoundEffect") then
        eq = Instance.new("EqualizerSoundEffect")
        eq.Name = "_MeowBassBoost"
        eq.Parent = sound
    end
    eq.LowGain = MusicPlayer.BassBoost and 10 or 0
    eq.MidGain = MusicPlayer.BassBoost and 0 or 0
    eq.HighGain = MusicPlayer.BassBoost and -5 or 0
    eq.Enabled = MusicPlayer.BassBoost == true
    MusicPlayer.Equalizer = eq

    local sg = Instance.new("ScreenGui")
    sg.Name = "_MeowMusicPlayerGui"
    sg.ResetOnSpawn = false
    sg.DisplayOrder = 1000
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function() sg.Parent = coreGui end)
    if not sg.Parent then
        pcall(function() sg.Parent = LocalPlayer:FindFirstChild("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui", 0.5) end)
    end
    MusicPlayer.Gui = sg
    shared.MeowMusicPlayer = MusicPlayer

    local main = Instance.new("Frame")
    main.Name = "MusicPlayerFrame"
    main.Size = UDim2.fromOffset(296, 475)
    main.Position = UDim2.new(1, -315, 0, 20)
    main.BackgroundColor3 = Color3.fromRGB(8, 9, 13)
    main.BorderSizePixel = 0
    local pendingVisible = getgenv and getgenv().MP_PendingVisible
    local shouldBeVisible = MusicPlayer.Visible == true
    if pendingVisible ~= nil then shouldBeVisible = pendingVisible == true end
    main.Visible = true
    main.ZIndex = 500
    main.Parent = sg
    MusicPlayer.MainFrame = main
    MusicPlayer.Visible = main.Visible

    Instance.new("UICorner", main).CornerRadius = UDim.new(0, 16)
    local stroke = Instance.new("UIStroke", main)
    stroke.Color = Color3.fromRGB(80, 120, 200)
    stroke.Thickness = 1
    stroke.Transparency = 0.7

    local accentLine = Instance.new("Frame")
    accentLine.Size = UDim2.new(1, -24, 0, 2)
    accentLine.Position = UDim2.fromOffset(12, 0)
    accentLine.BackgroundColor3 = MP_ACCENT
    accentLine.BorderSizePixel = 0
    accentLine.Parent = main
    mp_accent_part(accentLine, "BackgroundColor3")
    Instance.new("UICorner", accentLine).CornerRadius = UDim.new(1, 0)

    local dragging, dragStart, startPos
    main.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = main.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                end
            end)
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStart
            main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)

    local topBar = Instance.new("Frame")
    topBar.Size = UDim2.new(1, 0, 0, 32)
    topBar.BackgroundTransparency = 1
    topBar.Parent = main

    local blueDot = Instance.new("Frame")
    blueDot.Size = UDim2.fromOffset(8, 8)
    blueDot.Position = UDim2.fromOffset(12, 12)
    blueDot.BackgroundColor3 = MP_ACCENT
    mp_accent_part(blueDot, "BackgroundColor3")
    blueDot.BorderSizePixel = 0
    blueDot.BackgroundTransparency = 0.1
    blueDot.Parent = topBar
    Instance.new("UICorner", blueDot).CornerRadius = UDim.new(1, 0)

    local titleLabel = Instance.new("TextLabel")
