    local songRows = {}
    local function playTrack(idx)
        if idx < 1 then idx = #MusicPlayer.Playlist end
        if idx > #MusicPlayer.Playlist then idx = 1 end
        MusicPlayer.CurrentTrack = idx
        local item = MusicPlayer.Playlist[idx]

        pcall(function() sound:Stop() end)
        sound.SoundId = item.id
        sound.TimePosition = 0

        sound:Play()
        if not sound.IsLoaded then
            local conn
            conn = sound.Loaded:Connect(function()
                if MusicPlayer.Playing and sound.SoundId == item.id then
                    pcall(function() sound:Play() end)
                end
                if conn then pcall(function() conn:Disconnect() end) end
            end)
        end

        task.delay(2.5, function()
            if MusicPlayer.CurrentTrack ~= idx then return end
            if sound.IsLoaded then return end
            MP_UNAVAILABLE = MP_UNAVAILABLE or {}
            MP_UNAVAILABLE[idx] = true
            if songRows[idx] then
                songRows[idx].Title.TextColor3 = Color3.fromRGB(245, 74, 91)
                songRows[idx].Title.Text = "✕ " .. MusicPlayer.Playlist[idx].title
            end
            trackStatus.Text = "unavailable"

            task.delay(0.3, function()
                if MusicPlayer.CurrentTrack == idx and not sound.IsLoaded then
                    playTrack(idx + 1)
                end
            end)
        end)
        MusicPlayer.Playing = true
        playBtn.Text = "||"
        trackTitle.Text = item.title
        trackStatus.Text = "playing"
        trackSub.Text = "track " .. idx .. " of " .. #MusicPlayer.Playlist .. " · Community"
        totTimeLbl.Text = item.time

        for i, r in ipairs(songRows) do
            local isCur = (i == idx)
            local rowTitle = MusicPlayer.Playlist[i].title
            r.Button.BackgroundColor3 = isCur and Color3.fromRGB(21, 34, 50) or Color3.fromRGB(16, 17, 23)
            r.Title.TextColor3 = isCur and MP_ACCENT or Color3.fromRGB(190, 195, 205)
            r.Title.Text = (isCur and "... " or "") .. rowTitle
            r.Time.TextColor3 = isCur and MP_ACCENT or Color3.fromRGB(110, 115, 125)
        end
    end

    playBtn.MouseButton1Click:Connect(function()
        if MusicPlayer.Playing then
            sound:Pause()
            MusicPlayer.Playing = false
            playBtn.Text = ">"
            if MusicPlayer.PreviewPlayBtn then MusicPlayer.PreviewPlayBtn.Text = ">" end
            if MusicPlayer.PreviewFrame then MusicPlayer.PreviewFrame.Visible = false end
            trackStatus.Text = "ready"
        else
            if sound.SoundId == "" then
                playTrack(MusicPlayer.CurrentTrack)
            else
                sound:Resume()
                MusicPlayer.Playing = true
                playBtn.Text = "||"
                if MusicPlayer.PreviewPlayBtn then MusicPlayer.PreviewPlayBtn.Text = "||" end
                if MusicPlayer.PreviewFrame then MusicPlayer.PreviewFrame.Visible = true end
                trackStatus.Text = "playing"
            end
        end
    end)

    prevBtn.MouseButton1Click:Connect(function()
