    searchBox.FocusLost:Connect(function(enterPressed)
        local query = searchBox.Text:gsub("%s+", "")
        if #query > 0 then
            local cleanNum = query:gsub("%D+", "")
            if #cleanNum > 4 then
                pcall(function() sound:Stop() end)
                sound.SoundId = "rbxassetid://" .. cleanNum
                sound.TimePosition = 0
                sound:Play()
                if not sound.IsLoaded then
                    local conn
                    conn = sound.Loaded:Connect(function()
                        if MusicPlayer.Playing then pcall(function() sound:Play() end) end
                        if conn then pcall(function() conn:Disconnect() end) end
                    end)
                end
                MusicPlayer.Playing = true
                playBtn.Text = "||"
                trackTitle.Text = "Custom: " .. query
                trackStatus.Text = "playing"
                trackSub.Text = "Custom Audio Stream"
                if MusicPlayer.PreviewTitle then MusicPlayer.PreviewTitle.Text = "Custom: " .. query end
                if MusicPlayer.PreviewPlayBtn then MusicPlayer.PreviewPlayBtn.Text = "||" end
                return
            end
        end
    end)

