    RunService.Heartbeat:Connect(function()
        if MusicPlayer.Playing and sound.TimeLength > 0 then
            local pos = sound.TimePosition
            local len = sound.TimeLength
            local mins = math.floor(pos / 60)
            local secs = math.floor(pos % 60)
            curTimeLbl.Text = string.format("%d:%02d", mins, secs)
            if not progDragging then
                progFill.Size = UDim2.new(math.clamp(pos / len, 0, 1), 0, 1, 0)
            end

            local t = tick()
            if MusicPlayer.WaveBars then
                for b, bar in ipairs(MusicPlayer.WaveBars) do
                    local h = 6 + math.floor((math.sin(t*8 + b*1.3) * 0.5 + 0.5) * 26)
                    bar.Size = UDim2.new(0, 4, 0, math.clamp(h, 4, 32))
                end
            end
            if MusicPlayer.PreviewBars then
                for b, bar in ipairs(MusicPlayer.PreviewBars) do
                    local h = 6 + math.floor((math.sin(t*9 + b*1.7) * 0.5 + 0.5) * 30)
                    bar.Size = UDim2.new(0, 6, 0, math.clamp(h, 4, 36))
                end
            end
            if MusicPlayer.PreviewTime then
                local mins2 = math.floor(pos/60); local secs2 = math.floor(pos%60)
                MusicPlayer.PreviewTime.Text = string.format("%d:%02d / %s", mins2, secs2, MusicPlayer.Playlist[MusicPlayer.CurrentTrack].time)
            end
        else

            if MusicPlayer.WaveBars then
                for _, bar in ipairs(MusicPlayer.WaveBars) do bar.Size = UDim2.new(0, 4, 0, 4) end
            end
            if MusicPlayer.PreviewBars then
                for _, bar in ipairs(MusicPlayer.PreviewBars) do bar.Size = UDim2.new(0, 6, 0, 4) end
            end
        end
    end)



