    mp_accent_part(pPlay, "BackgroundColor3")
    MusicPlayer.PreviewPlayBtn = pPlay

    local pNext = Instance.new("TextButton")
    pNext.Size = UDim2.fromOffset(30, 20)
    pNext.Position = UDim2.fromOffset(76, 1)
    pNext.BackgroundColor3 = Color3.fromRGB(16, 18, 26)
    pNext.BackgroundTransparency = 0.2
    pNext.Text = ">|"
    pNext.TextColor3 = Color3.fromRGB(210, 215, 235)
    pNext.Font = MP_FONT_BOLD
    pNext.TextSize = 10
    pNext.Parent = pControls
    Instance.new("UICorner", pNext).CornerRadius = UDim.new(0, 6)

    local pRand = Instance.new("TextButton")
    pRand.Size = UDim2.fromOffset(30, 20)
    pRand.Position = UDim2.fromOffset(112, 1)
    pRand.BackgroundColor3 = Color3.fromRGB(16, 18, 26)
    pRand.BackgroundTransparency = 0.2
    pRand.Text = "Shuffle"
    pRand.Size = UDim2.fromOffset(56, 20)
    pRand.TextColor3 = Color3.fromRGB(210, 215, 235)
    pRand.Font = MP_FONT_BOLD
    pRand.TextSize = 9
    pRand.Parent = pControls
    Instance.new("UICorner", pRand).CornerRadius = UDim.new(0, 6)

    pPrev.MouseButton1Click:Connect(function() playTrack(MusicPlayer.CurrentTrack - 1) end)
    pNext.MouseButton1Click:Connect(function()
        if MusicPlayer.Shuffle then playTrack(math.random(1, #MusicPlayer.Playlist))
        else playTrack(MusicPlayer.CurrentTrack + 1) end
    end)
    pRand.MouseButton1Click:Connect(function() playTrack(math.random(1, #MusicPlayer.Playlist)) end)
    pPlay.MouseButton1Click:Connect(function()
        if MusicPlayer.Playing then
            sound:Pause(); MusicPlayer.Playing = false; pPlay.Text = ">"; playBtn.Text = ">"
            if MusicPlayer.PreviewFrame then MusicPlayer.PreviewFrame.Visible = false end
        else
            if sound.SoundId == "" then playTrack(MusicPlayer.CurrentTrack)
            else sound:Resume(); MusicPlayer.Playing = true; pPlay.Text = "||"; playBtn.Text = "||"
                if MusicPlayer.PreviewFrame then MusicPlayer.PreviewFrame.Visible = true end end
        end
    end)


    local function syncPreview()
        local item = MusicPlayer.Playlist[MusicPlayer.CurrentTrack]
        if not item then return end
        if MusicPlayer.PreviewTitle then MusicPlayer.PreviewTitle.Text = item.title end
        if MusicPlayer.PreviewTime then MusicPlayer.PreviewTime.Text = "0:00 / " .. item.time end
        if MusicPlayer.PreviewPlayBtn then MusicPlayer.PreviewPlayBtn.Text = MusicPlayer.Playing and "||" or ">" end
        if MusicPlayer.PreviewFrame then MusicPlayer.PreviewFrame.Visible = MusicPlayer.Playing end
    end
    MusicPlayer.SyncPreview = syncPreview


    local _origPlayTrack = playTrack
    playTrack = function(idx)
        _origPlayTrack(idx)
        if MusicPlayer.SyncPreview then MusicPlayer.SyncPreview() end
    end


    getgenv().MP_REFRESH_MODES = function()
        local accent = MP_ACCENT
        local gray = Color3.fromRGB(150, 155, 168)
        local dark = Color3.fromRGB(28, 30, 40)
        if shufBtn then shufBtn.TextColor3 = MusicPlayer.Shuffle and accent or gray end
        if shufStroke then shufStroke.Color = MusicPlayer.Shuffle and accent or dark end
        if repBtn then repBtn.TextColor3 = MusicPlayer.RepeatAll and accent or gray end
        if repStroke then repStroke.Color = MusicPlayer.RepeatAll and accent or dark end
        if bassBtn then bassBtn.TextColor3 = MusicPlayer.BassBoost and accent or gray end
        if bassStroke then bassStroke.Color = MusicPlayer.BassBoost and accent or dark end
        if normBtn then normBtn.TextColor3 = MusicPlayer.NormalMode and accent or gray end
        if normStroke then normStroke.Color = MusicPlayer.NormalMode and accent or dark end
    end
end


getgenv().MP_TOGGLE_KEY = getgenv().MP_TOGGLE_KEY or Enum.KeyCode.M
if MusicPlayer.ToggleConnection then
    pcall(function() MusicPlayer.ToggleConnection:Disconnect() end)
    MusicPlayer.ToggleConnection = nil
end
MusicPlayer.ToggleConnection = UserInputService.InputBegan:Connect(function(input, gp)
    if gp then return end
    local key = getgenv().MP_TOGGLE_KEY or Enum.KeyCode.M
    if input.KeyCode == key then
        if MusicPlayer and MusicPlayer.MainFrame then
            MusicPlayer.MainFrame.Visible = not MusicPlayer.MainFrame.Visible
            MusicPlayer.Visible = MusicPlayer.MainFrame.Visible
            if MusicPlayer.Gui then MusicPlayer.Gui.Enabled = true end
            if flags then flags.show_music_player = MusicPlayer.MainFrame.Visible end
        end
    end
end)

getgenv().MP_Init = initMusicPlayer

task.spawn(function()
    initMusicPlayer()
    local gv = getgenv()
    if gv.MP_PendingVisible ~= nil then
        MP_SetVisible(gv.MP_PendingVisible)
    end
    if gv.MP_PendingAccent ~= nil then
        MP_ApplyAccent(gv.MP_PendingAccent)
    end
end)
